 T("default R010 compatibility preserves control rejection",()=>{C(Chart.Parse(Aff("control")).JudgmentUnits==2,"ordinary");foreach(string n in new[]{"camera","lanes"}){bool rejected=false;try{Chart.Parse(Aff(n));}catch(NotSupportedException){rejected=true;}C(rejected,"default profile must reject scene controls");}});
 T("unsupported duration direction mode multiplicity group and malformed syntax reject",()=>{string good=Aff("camera");foreach(string bad in new[]{good.Replace("500.00,1","0.00,1"),good.Replace("500.00,1","-5.00,1"),good.Replace("500.00,1","NaN,1"),good.Replace("500.00,1","500,1"),good.Replace("500.00,1","500.00,0"),good.Replace("enwidencamera","trackdisplay"),good.Replace("(1500,2);","scenecontrol(600,enwidenlanes,500.00,1);(1500,2);"),good.Replace("scenecontrol(500,enwidencamera,500.00,1);","timinggroup(){timing(0,60.00,4.00);scenecontrol(500,enwidencamera,500.00,1);(1500,1);};")}){bool rejected=false;try{Parse(bad);}catch(NotSupportedException){rejected=true;}C(rejected,"explicit supported boundary");}});
 foreach(string n in new[]{"control","camera","lanes"})T("native scalar trajectory "+n,()=>{var k=New(n);var frames=new List<object>();int i=0;foreach(var e in new[]{500,501,502,750,1000,1500,1501}){F(k,e);Eq(k.Widening.G,n=="camera"?oracle.GetProperty("cameraG")[i].GetSingle():1,n+" G E"+e);Eq(k.Widening.W,n=="lanes"?oracle.GetProperty("lanesW")[i].GetSingle():0,n+" W E"+e);frames.Add(Snapshot(k));i++;}native.Add(new{scenario=n,frames});});
 T("strict equality then interpolation before dispatch and next-frame removal",()=>{var k=New("camera");F(k,500);C(!k.Widening.Controls[0].Processed,"equality");F(k,501);var c=k.Widening.Controls[0];C(c.Processed&&c.Active&&c.DispatchedAt==501&&k.Widening.LastFrameOperations[0]=="INTERPOLATE"&&k.Widening.LastFrameOperations.Count==2,"original order");Eq(k.Widening.G,1,"501 old parameters");F(k,502);C(!c.Active,"processed removal separate from dispatch");C(k.Widening.Camera.Start==500&&k.Widening.Lanes.Owner==null,"original event anchor / independent field ownership");Eq(k.Widening.PreviousG,1,"previousG");F(k,750);Eq(k.Widening.PreviousG,1.0019999742507935f,"previous sampled G");});
