 T("large initial jump retains dispatch-after-interpolation contract",()=>{var k=New("camera");F(k,750);Eq(k.Widening.G,1,"late dispatch old state");C(k.Widening.Camera.Start==500&&k.Widening.Controls[0].DispatchedAt==750,"not dispatch-time anchor");F(k,1000);Eq(k.Widening.G,1.5f,"next frame uses elapsed since500");F(k,1000);C(k.Widening.LastFrameOperations.Count==1,"once-only");});
 T("positive larger duration derives interpolation rather than fitting samples",()=>{foreach(string n in new[]{"camera","lanes"}){var k=new Kernel(Parse(Practice(n)));k.Frame(0);k.Frame(3002);F(k,2000);F(k,2001);F(k,2500);Eq(n=="camera"?k.Widening.G:k.Widening.W,n=="camera"?1.25f:.5f,"1000ms duration midpoint");C(k.Widening.Controls[0].Data.Duration==1000,"typed duration");}});
 T("E004 real-coordinate primary secondary depth and truncation controls",()=>{foreach(string n in new[]{"control","camera","lanes"}){var k=New(n);Prepare(k);int i=0;foreach(float x in new[]{40f,950f}){var p=GroundSpatial.Select(new SkyPoint(x,0,0),k.Widening.G,k.Widening.W);var exp=oracle.GetProperty("pairs").GetProperty(n)[i++];C(p.Primary==exp[0].GetInt32()&&p.Secondary==exp[1].GetInt32(),n+" pair");}C(!GroundSpatial.Select(new SkyPoint(40,0,500),k.Widening.G,k.Widening.W).Any&&!GroundSpatial.Select(new SkyPoint(40,0,-500),k.Widening.G,k.Widening.W).Any,"strict depth");}C(GroundSpatial.Select(new SkyPoint(425.9f,0,0),1,0).Primary==0,"truncated425 asymmetry");C(GroundSpatial.Select(new SkyPoint(-425.9f,0,0),1,0).Primary==3,"signed truncation");C(GroundSpatial.Select(new SkyPoint(850,0,0),1,1).Primary==5&&GroundSpatial.Select(new SkyPoint(851,0,0),1,1).Primary==6,"strict outer");C(!GroundSpatial.Select(new SkyPoint(float.NaN,0,0),1,0).Any,"nonfinite");});
 foreach(string n in new[]{"control","camera","lanes"})T("E039 ground-input native judgment and cleanup "+n,()=>{var k=New(n);Prepare(k);var events=new List<object>();int pointer=40;foreach(float x in new[]{40f,950f}){k.DownGround(4502,pointer,new SkyPoint(x,0,0));var contact=k.Contacts.Single();int expectedLane=x==40?4:n=="lanes"?6:5;C(contact.Lane==expectedLane,"primary retained");C(contact.SecondaryLane==(n=="camera"&&x==40?3:0),"secondary retained");events.Add(Snapshot(k));k.Up(pointer++);C(k.ContactCount==0,"UP mapping cleanup");}int p=n=="control"?0:1;C(k.Pure==p&&k.Shining==p&&k.Far==0&&k.Lost==0&&k.Combo==p&&k.Score==(p==0?0:5000001),"native counters/score");Eq(k.Health,p==0?0:40.20000076293945f,"native float health");C(k.Notes.Count(t=>t.Consumed)==p,"consumed identity");if(p==1)C(k.Notes.Single(t=>t.Consumed).Lane==(n=="camera"?3:6),"target lane");F(k,1501);C(k.Pure==p&&!k.Finished&&k.RecorderTrace.Count==0,"no duplicate or native results claim");native.Add(new{scenario=n,inputs=events,after1501=Snapshot(k)});});
 T("fresh duplicate contact reaches consumed guard without another award",()=>{var k=New("camera");Prepare(k);k.DownGround(4502,100,new SkyPoint(40,0,0));int id=k.Contacts.Single().Id;k.Up(100);k.DownGround(4502,101,new SkyPoint(40,0,0));C(k.Contacts.Single().Id!=id&&k.Candidates.Count==1&&k.Classifications.Single().Outcome=="guard_consumed"&&k.Pure==1&&k.RecorderTrace.Count==0,"fresh ID + same eligibility + consumed guard");k.Cancel(101);});
 T("noinput stays indexed and cannot use widened secondary eligibility",()=>{var aff=Aff("camera")+"\ntiminggroup(noinput){timing(0,60.00,4.00);(1500,2);};\n";var k=new Kernel(Parse(aff));k.Frame(0);k.Frame(3002);Prepare(k);k.DownGround(4502,1,new SkyPoint(40,0,0));C(k.Chart.JudgmentUnits==2&&k.Pure==1&&k.Candidates.Count==1&&k.Notes.Single(n=>!n.InputEnabled).Consumed==false,"disabled filter");F(k,1621);C(k.Lost==1&&k.Pure==1&&!k.Notes.Single(n=>!n.InputEnabled).Missed,"noinput expiry unaffected");});
 T("retained world MOVE updates both lanes without new DOWN or judgment",()=>{var k=New("camera");Prepare(k);k.DownGround(4502,1,new SkyPoint(950,0,0));int id=k.Contacts.Single().Id;k.MoveGround(1,new SkyPoint(40,0,0));C(k.Pure==0&&k.Contacts.Single().Id==id&&k.Contacts.Single().SecondaryLane==3,"MOVE transport");F(k,1501);C(k.Pure==0,"frame cannot create tap");k.Cancel(1);C(k.ContactCount==0,"cancel");});
 T("pause60seconds freezes widening and resume advances one effective millisecond",()=>{var c=new Clock();var s=new GameplaySession(c);s.Start(Aff("camera"),profile:ChartProfile.S01Mixed);c.Milliseconds=3002;s.Frame();foreach(int e in new[]{500,501,750}){c.Milliseconds=e+3002;s.Frame();}s.GroundPointer(1,new SkyPoint(40,0,0),null,true);int id=s.Core!.Contacts.Single().Id;C(s.Pause(),"pause");c.Milliseconds+=60000;s.Frame();Eq(s.Core.Widening.G,1.25f,"frozen G");C(s.Core.Timeline.EffectiveTime==750&&s.Core.Contacts.Single().Id==id&&!s.GroundPointer(2,new SkyPoint(40,0,0),null,true),"frozen modal");C(s.Resume(),"explicit resume");c.Milliseconds++;s.Frame();Eq(s.Core.Widening.G,oracle.GetProperty("engineeringG751FromE007FloatStages").GetSingle(),"next effective frame");C(s.Core.Widening.Controls[0].DispatchedAt==501,"no duplicate dispatch");s.Home();});
 T("paused UP CANCEL and focus reset contacts and replay transitions",()=>{var c=new Clock();var s=new GameplaySession(c);s.Start(Aff("lanes"),profile:ChartProfile.S01Mixed);c.Milliseconds=3002;s.Frame();foreach(int e in new[]{501,1500}){c.Milliseconds=e+3002;s.Frame();}s.GroundPointer(1,new SkyPoint(950,0,0),null,true);s.GroundPointer(2,new SkyPoint(-950,0,0),null,true);s.Pause();C(s.Cancel(1)&&s.GroundPointer(2,new SkyPoint(-950,0,0),null,false)&&s.Core!.ContactCount==0,"paused cleanup");s.Resume();s.FocusLost();s.FocusReturned();C(s.PauseModalActive&&s.Core!.Paused,"no auto resume");s.Start(Aff("lanes"),profile:ChartProfile.S01Mixed);C(s.Core!.Widening.G==1&&s.Core.Widening.W==0&&s.Core.ContactCount==0&&s.Core.Widening.Controls.All(x=>!x.Processed)&&s.Core.Pure==0,"fresh session");s.Home();});
